// Everything downstream needs stable identifiers that survive every
// success and failure branch, created before any API/OCR call is made.
// No weak fallback: a missing crypto.randomUUID must fail visibly rather
// than mint a low-entropy identity for evidence.
// The n8n JS Task Runner sandbox does not expose a bare `crypto` global
// (confirmed against the real pinned n8nio/n8n:2.33.7 image) -- the built-in
// must be required explicitly, and require() itself is denied unless
// allow-listed (NODE_FUNCTION_ALLOW_BUILTIN=crypto, set on the n8n
// container -- see docker-compose.phase1-upload-demo.yml). Same pattern as
// Flow 1a's "Build run context" nodes: a single guarded require("crypto")
// reference is reused for both the UUIDs and the pdf hash below, instead of
// an earlier round's second, unguarded require('crypto').createHash(...)
// call, which crashed this node -- and with it the whole execution, before
// any of this workflow's own error handling ever ran -- whenever
// NODE_FUNCTION_ALLOW_BUILTIN=crypto was not set (found 2026-08-25: this is
// what produced the empty HTTP 200 the missing-Gemini-credential case used
// to return).
let nodeCrypto;
try {
  nodeCrypto = require("crypto");
} catch (e) {
  nodeCrypto = undefined;
}
if (!nodeCrypto || typeof nodeCrypto.randomUUID !== "function") {
  throw new Error(
    "SECURE_UUID_UNAVAILABLE: refusing to mint a weak identifier for correlationId/processInstanceId without crypto.randomUUID() (require(\"crypto\") must be allow-listed via NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance)."
  );
}
const correlationId = nodeCrypto.randomUUID();
const processInstanceId = nodeCrypto.randomUUID();

const item = $input.first();
const body = item.json.body || {};
// "data" matches the unmodified "02.1 Encode PDF for OCR" node's binaryPropertyName.
const invoiceFile = item.binary ? item.binary.data : undefined;
const pdfSha256 = invoiceFile
  ? nodeCrypto.createHash("sha256").update(await this.helpers.getBinaryDataBuffer(0, "data")).digest("hex")
  : null;

const demoModeRequested = body.demoMode === "true" || body.demoMode === true;
const submittedOrganizationId =
  typeof body.organizationId === "string" && body.organizationId.trim() !== ""
    ? body.organizationId.trim()
    : null;
// Never a silent fallback -- only demoMode=true selects the fictional org.
const organizationId =
  submittedOrganizationId || (demoModeRequested ? "unternehmen-x-demo" : null);

// AI-execution-profile selection (2026-08-11, dev-stack/AI-selection round):
// the browser sends only a stable profile ID -- never a provider URL, model
// name, or credential. An absent/blank value stays null and is handled by
// "01.9 Resolve AI execution profile" as "unknown", never defaulted to cloud.
const submittedAiExecutionProfile =
  typeof body.aiExecutionProfile === "string" && body.aiExecutionProfile.trim() !== ""
    ? body.aiExecutionProfile.trim()
    : null;

return [
  {
    json: {
      correlationId,
      processInstanceId,
      receivedAt: new Date().toISOString(),
      hasFile: Boolean(invoiceFile),
      filename: invoiceFile ? invoiceFile.fileName : null,
      mimeType: invoiceFile ? invoiceFile.mimeType : null,
      pdfSha256,
      organizationId,
      demoModeRequested,
      processingPath: "pdf_ocr",
      aiExecutionProfile: submittedAiExecutionProfile,
    },
    binary: item.binary,
  },
];

// Deterministic 4xx-shaped input/contract checks -- no OCR call has been
// made yet, so nothing here is a "technical" failure and nothing here is
// ever retried.
//
// Every branch must carry `binary` forward explicitly -- unlike an IF or
// Switch node, a Code node's returned item is a brand-new object, and
// omitting `binary` here silently drops the uploaded file for every node
// downstream (found 2026-08-11 via a live n8n execution: "02.1 Encode PDF
// for OCR" crashed with an opaque "Unknown error" because $input.first().
// binary was empty by the time it ran -- not a credential or Gemini issue
// at all, this node was the actual break in the chain).
const input = $input.first();
const ctx = input.json;

if (!ctx.hasFile) {
  return [{ json: { ...ctx, valid: false, errorCode: "MISSING_INVOICE_FILE", explanation: "No PDF binary field named 'data' was present in the upload. Not retried: this is an input/contract error, not a service failure." }, binary: input.binary }];
}
if (!ctx.organizationId) {
  return [{ json: { ...ctx, valid: false, errorCode: "ORGANIZATION_CONTEXT_REQUIRED", explanation: "organizationId was not provided and demoMode was not set. Pass organizationId explicitly, or demoMode=true to use the fictional unternehmen-x-demo organization. Not retried: this is an input/contract error, not a service failure." }, binary: input.binary }];
}
return [{ json: { ...ctx, valid: true }, binary: input.binary }];

// AI-execution-profile resolution (2026-08-11, dev-stack/AI-selection
// round). The browser sends only a stable profile ID -- provider URLs,
// model names, and credentials are resolved here, server-side, and never
// travel to or from the browser. No profile ID ever defaults to cloud:
// a missing/unknown ID is classified "unknown" and fails safely downstream
// (01.11), and an unconfigured local endpoint is classified
// "local_unavailable" rather than silently trying (and definitely never
// silently falling back to cloud).
const PROFILE_REGISTRY = {
  "local-default": {
    aiProvider: "local-openai-compatible",
    modelId: $env.LOCAL_LLM_MODEL || "local-default-model",
    modelVersion: null,
    processingLocation: "local",
    promptVersion: "flow1b-extract-v1",
  },
  "cloud-gemini": {
    aiProvider: "google-gemini",
    modelId: "gemini-2.5-pro",
    modelVersion: null,
    processingLocation: "cloud",
    promptVersion: "flow1b-extract-v1",
  },
};

const ctx = $input.first().json;
const requested = ctx.aiExecutionProfile;
const known = requested ? PROFILE_REGISTRY[requested] : null;

let profileStatus;
if (!known) {
  profileStatus = "unknown";
} else if (requested === "local-default" && !($env.LOCAL_LLM_BASE_URL || "").trim()) {
  // Configured-availability check only -- a genuine runtime connection
  // failure at call time is still caught by 02.3L's own error branch.
  profileStatus = "local_unavailable";
} else if (requested === "local-default") {
  profileStatus = "local";
} else {
  profileStatus = "cloud";
}

return [
  {
    json: {
      ...ctx,
      aiProfileStatus: profileStatus,
      resolvedProfile: known,
    },
    binary: $input.first().binary,
  },
];

const binaryPropertyName = 'data';
const result = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryPropertyName);

  result.push({
    json: {
      pdfMimeType: 'application/pdf',
      pdfBase64: buffer.toString('base64')
    }
  });
}

return result;

function extractTextFromGeminiResponse(item) {
  const j = item.json || {};

  if (
    Array.isArray(j.candidates) &&
    j.candidates[0] &&
    j.candidates[0].content &&
    Array.isArray(j.candidates[0].content.parts) &&
    j.candidates[0].content.parts[0] &&
    typeof j.candidates[0].content.parts[0].text === 'string'
  ) {
    return j.candidates[0].content.parts[0].text;
  }

  throw new Error('Could not find Gemini text output in expected response fields.');
}

function stripMarkdownFences(text) {
  return text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function ensureField(obj, key) {
  return typeof obj[key] === 'string' && obj[key].trim()
    ? obj[key].trim()
    : 'not found';
}

function ensureLineItems(obj) {
  const raw = obj['Line Items'];
  if (!Array.isArray(raw)) return [];
  return raw.map((li) => ({
    Description: typeof li['Description'] === 'string' && li['Description'].trim() ? li['Description'].trim() : 'not found',
    Quantity: li['Quantity'],
    'Net Amount': li['Net Amount'],
    'VAT Rate': li['VAT Rate'],
  }));
}

const profile = $('01.9 Resolve AI execution profile').item.json.resolvedProfile;

return items.map(item => {
  const rawText = extractTextFromGeminiResponse(item);
  const cleaned = stripMarkdownFences(rawText);

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    throw new Error(`Gemini output is not valid JSON. Raw output: ${cleaned}`);
  }

  const normalized = {
    'Invoice No': ensureField(parsed, 'Invoice No'),
    'Invoice Date': ensureField(parsed, 'Invoice Date'),
    'Type Code': ensureField(parsed, 'Type Code'),
    'Currency': ensureField(parsed, 'Currency'),
    'VAT-ID (Seller)': ensureField(parsed, 'VAT-ID (Seller)'),
    'VAT-ID (Buyer)': ensureField(parsed, 'VAT-ID (Buyer)'),
    'Tax ID (Seller)': ensureField(parsed, 'Tax ID (Seller)'),
    'Tax ID (Buyer)': ensureField(parsed, 'Tax ID (Buyer)'),
    'Name (Seller)': ensureField(parsed, 'Name (Seller)'),
    'Address (Seller)': ensureField(parsed, 'Address (Seller)'),
    'Zip (Seller)': ensureField(parsed, 'Zip (Seller)'),
    'City (Seller)': ensureField(parsed, 'City (Seller)'),
    'Country (Seller)': ensureField(parsed, 'Country (Seller)'),
    'Name (Buyer)': ensureField(parsed, 'Name (Buyer)'),
    'Address (Buyer)': ensureField(parsed, 'Address (Buyer)'),
    'Zip (Buyer)': ensureField(parsed, 'Zip (Buyer)'),
    'City (Buyer)': ensureField(parsed, 'City (Buyer)'),
    'Country (Buyer)': ensureField(parsed, 'Country (Buyer)'),
    'Supply Description': ensureField(parsed, 'Supply Description'),
    'Delivery Date': ensureField(parsed, 'Delivery Date'),
    'Period Start': ensureField(parsed, 'Period Start'),
    'Period End': ensureField(parsed, 'Period End'),
    'Net Total': parsed['Net Total'],
    'Tax Basis': parsed['Tax Basis'],
    'Tax Amount': parsed['Tax Amount'],
    'Gross Total': parsed['Gross Total'],
    'Payable Amount': parsed['Payable Amount'],
    'Charge Total': parsed['Charge Total'],
    'Allowance Total': parsed['Allowance Total'],
    'Prepaid Amount': parsed['Prepaid Amount'],
    'Rounding Amount': parsed['Rounding Amount'],
    'Line Items': ensureLineItems(parsed)
  };

  return {
    json: {
      invoice_extracted: normalized,
      gemini_raw_text: rawText,
      aiMeta: {
        aiProvider: profile.aiProvider,
