// Assembles the canonical invoice contract in
// facturx/phase1/schemas/canonical_invoice.schema.json exactly (same
// document/extraction/invoice/fieldEvidence shape, schemaVersion "1.0.0")
// so this node's output can be submitted directly to the real Phase 1 API's
// POST /v1/invoices/process-extracted (see "03.1 Run DigiTax controls"
// below) -- this is the API-convergence fix for the A1 review's "Flow 1b
// does not use the canonical Phase-1 control API" finding. Buyer master
// data is no longer looked up here at all: the real API resolves
// organization context (and evaluates ORG-001 against it) itself, from
// organizationId alone, so there is nothing left in n8n to keep in sync by
// hand.
//
// Shared by both provider lanes (2026-08-11, dev-stack/AI-selection round;
// expanded to the full schema 2026-08-18): "02.5 Parse OCR/LLM output"
// (cloud) and "02.5L Parse local OCR/LLM output" (local) both emit the
// same {invoice_extracted, aiMeta} shape, so this single node produces one
// identical canonical contract regardless of which lane ran -- per the
// AI-selection spec's convergence requirement.
const PLACEHOLDER_FOUND_CONFIDENCE = 0.85;
const parsed = $input.first().json;
const g = parsed.invoice_extracted;

function emit(rawValue, locator) {
  const found = typeof rawValue === "string" && rawValue.trim() && rawValue.trim().toLowerCase() !== "not found";
  return {
    value: found ? rawValue.trim() : null,
    evidence: {
      method: "llm",
      confidence: found ? PLACEHOLDER_FOUND_CONFIDENCE : 0.0,
      locator,
      rawValue: rawValue,
      state: found ? "extracted" : "not_extracted",
    },
  };
}

// Coerces a model-reported amount (already a JSON number in the happy
// path, but defensively also accepts a string with German "1.234,56" or
// plain "1234.56" formatting) to a JS number, or null if not parseable.
function numOrNull(v) {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v !== "string") return null;
  const t = v.trim();
  if (!t || t.toLowerCase() === "not found") return null;
  const cleaned = t.replace(/[^\d,.-]/g, "");
  const normalized = cleaned.includes(",") && cleaned.includes(".")
    ? cleaned.replace(/\./g, "").replace(",", ".")
    : cleaned.replace(",", ".");
  const n = parseFloat(normalized);
  return Number.isFinite(n) ? n : null;
}

function emitNum(rawValue, locator) {
  const n = numOrNull(rawValue);
  const found = n !== null;
  return {
    value: n,
    evidence: {
      method: "llm",
      confidence: found ? PLACEHOLDER_FOUND_CONFIDENCE : 0.0,
      locator,
      rawValue: rawValue,
      state: found ? "extracted" : "not_extracted",
    },
  };
}

function emitCode(rawValue, locator, validator) {
  const candidate = typeof rawValue === "string" ? rawValue.trim().toUpperCase() : null;
  const value = candidate && validator(candidate) ? candidate : null;
  const found = value !== null;
  return {
    value,
    evidence: {
      method: "llm",
      confidence: found ? PLACEHOLDER_FOUND_CONFIDENCE : 0.0,
      locator,
      rawValue: rawValue,
      state: found ? "extracted" : "not_extracted",
    },
  };
}
const isCurrency = (v) => /^[A-Z]{3}$/.test(v);
const isCountry = (v) => /^[A-Z]{2}$/.test(v);

const invoiceNumber = emit(g["Invoice No"], "invoice.invoiceNumber");
const issueDate = emit(g["Invoice Date"], "invoice.issueDate");
const typeCode = emit(g["Type Code"], "invoice.typeCode");
const currency = emitCode(g["Currency"], "invoice.currency", isCurrency);

const supplierName = emit(g["Name (Seller)"], "invoice.supplier.name");
const supplierVatId = emit(g["VAT-ID (Seller)"], "invoice.supplier.vatId");
const supplierTaxId = emit(g["Tax ID (Seller)"], "invoice.supplier.taxId");
const supplierStreet = emit(g["Address (Seller)"], "invoice.supplier.address.street");
const supplierPostal = emit(g["Zip (Seller)"], "invoice.supplier.address.postalCode");
const supplierCity = emit(g["City (Seller)"], "invoice.supplier.address.city");
const supplierCountry = emitCode(g["Country (Seller)"], "invoice.supplier.address.countryCode", isCountry);

const buyerName = emit(g["Name (Buyer)"], "invoice.buyer.name");
const buyerVatId = emit(g["VAT-ID (Buyer)"], "invoice.buyer.vatId");
const buyerTaxId = emit(g["Tax ID (Buyer)"], "invoice.buyer.taxId");
const buyerStreet = emit(g["Address (Buyer)"], "invoice.buyer.address.street");
const buyerPostal = emit(g["Zip (Buyer)"], "invoice.buyer.address.postalCode");
const buyerCity = emit(g["City (Buyer)"], "invoice.buyer.address.city");
const buyerCountry = emitCode(g["Country (Buyer)"], "invoice.buyer.address.countryCode", isCountry);

const supplyDescription = emit(g["Supply Description"], "invoice.supply.description");
const deliveryDate = emit(g["Delivery Date"], "invoice.supply.deliveryDate");
const periodStart = emit(g["Period Start"], "invoice.supply.periodStart");
const periodEnd = emit(g["Period End"], "invoice.supply.periodEnd");

const lineNet = emitNum(g["Net Total"], "invoice.totals.lineNet");
const taxBasis = emitNum(g["Tax Basis"], "invoice.totals.taxBasis");
const taxAmount = emitNum(g["Tax Amount"], "invoice.totals.taxAmount");
const grossAmount = emitNum(g["Gross Total"], "invoice.totals.grossAmount");
const payableAmount = emitNum(g["Payable Amount"], "invoice.totals.payableAmount");
const chargeTotal = emitNum(g["Charge Total"], "invoice.totals.chargeTotal");
const allowanceTotal = emitNum(g["Allowance Total"], "invoice.totals.allowanceTotal");
const prepaidAmount = emitNum(g["Prepaid Amount"], "invoice.totals.prepaidAmount");
const roundingAmount = emitNum(g["Rounding Amount"], "invoice.totals.roundingAmount");

const lineItems = Array.isArray(g["Line Items"])
  ? g["Line Items"].map((li) => ({
      description: (typeof li["Description"] === "string" && li["Description"].trim() && li["Description"].trim().toLowerCase() !== "not found")
        ? li["Description"].trim()
        : null,
      quantity: numOrNull(li["Quantity"]),
      netAmount: numOrNull(li["Net Amount"]),
      vatRate: numOrNull(li["VAT Rate"]),
    }))
  : [];

const fieldEvidence = {
  "invoice.invoiceNumber": invoiceNumber.evidence,
  "invoice.issueDate": issueDate.evidence,
  "invoice.typeCode": typeCode.evidence,
  "invoice.currency": currency.evidence,
  "invoice.supplier.name": supplierName.evidence,
  "invoice.supplier.vatId": supplierVatId.evidence,
  "invoice.supplier.taxId": supplierTaxId.evidence,
  "invoice.supplier.address.street": supplierStreet.evidence,
  "invoice.supplier.address.postalCode": supplierPostal.evidence,
  "invoice.supplier.address.city": supplierCity.evidence,
  "invoice.supplier.address.countryCode": supplierCountry.evidence,
  "invoice.buyer.name": buyerName.evidence,
  "invoice.buyer.vatId": buyerVatId.evidence,
  "invoice.buyer.taxId": buyerTaxId.evidence,
  "invoice.buyer.address.street": buyerStreet.evidence,
  "invoice.buyer.address.postalCode": buyerPostal.evidence,
  "invoice.buyer.address.city": buyerCity.evidence,
  "invoice.buyer.address.countryCode": buyerCountry.evidence,
  "invoice.supply.description": supplyDescription.evidence,
  "invoice.supply.deliveryDate": deliveryDate.evidence,
  "invoice.supply.periodStart": periodStart.evidence,
  "invoice.supply.periodEnd": periodEnd.evidence,
  "invoice.totals.lineNet": lineNet.evidence,
  "invoice.totals.taxBasis": taxBasis.evidence,
  "invoice.totals.taxAmount": taxAmount.evidence,
  "invoice.totals.grossAmount": grossAmount.evidence,
  "invoice.totals.payableAmount": payableAmount.evidence,
  "invoice.totals.chargeTotal": chargeTotal.evidence,
  "invoice.totals.allowanceTotal": allowanceTotal.evidence,
  "invoice.totals.prepaidAmount": prepaidAmount.evidence,
  "invoice.totals.roundingAmount": roundingAmount.evidence,
};

const invoice = {
  invoiceNumber: invoiceNumber.value,
  issueDate: issueDate.value,
  typeCode: typeCode.value,
  currency: currency.value,
  supplier: {
    name: supplierName.value,
    address: {
      street: supplierStreet.value,
      postalCode: supplierPostal.value,
      city: supplierCity.value,
      countryCode: supplierCountry.value,
    },
    taxId: supplierTaxId.value,
    vatId: supplierVatId.value,
  },
  buyer: {
    name: buyerName.value,
    address: {
      street: buyerStreet.value,
      postalCode: buyerPostal.value,
      city: buyerCity.value,
      countryCode: buyerCountry.value,
    },
    taxId: buyerTaxId.value,
    vatId: buyerVatId.value,
  },
  supply: {
    description: supplyDescription.value,
    deliveryDate: deliveryDate.value,
    periodStart: periodStart.value,
    periodEnd: periodEnd.value,
  },
  totals: {
    lineNet: lineNet.value,
    taxBasis: taxBasis.value,
    taxAmount: taxAmount.value,
    grossAmount: grossAmount.value,
    payableAmount: payableAmount.value,
    chargeTotal: chargeTotal.value,
    allowanceTotal: allowanceTotal.value,
    prepaidAmount: prepaidAmount.value,
    roundingAmount: roundingAmount.value,
  },
  lineItems,
};

const ctx = $('01.2 Build run context').item.json;

// document.sha256 is computed once upstream in "01.2 Build run context"
// from the same uploaded buffer this normalization ultimately describes;
// this node only ever runs after "01.4 Has valid upload?" confirmed a file
// is present, so ctx.pdfSha256 should always be set here.
const document = {
  filename: ctx.filename || "unknown.pdf",
  mimeType: ctx.mimeType || "application/pdf",
  sha256: ctx.pdfSha256 || "0".repeat(64),
};

const scalarEvidences = Object.values(fieldEvidence);
const extractedCount = scalarEvidences.filter((e) => e.state === "extracted").length;
// Transparent, non-calibrated proxy: fraction of the tracked scalar fields
// the model actually reported a value for. Not a confidence signal about
// correctness, only about completeness -- consistent with the placeholder
// per-field confidences above.
const overallConfidence = scalarEvidences.length
  ? Number((extractedCount / scalarEvidences.length).toFixed(3))
  : 0;
const coreFieldsFound = Boolean(invoiceNumber.value && issueDate.value && grossAmount.value !== null);

const extraction = {
  status: coreFieldsFound ? "completed" : "partial",
  overallConfidence,
  adapterVersion: null,
  warnings: [
    "Concept implementation: per-field confidence is a fixed placeholder (0.85 extracted / 0.0 not extracted), not a calibrated signal from the model.",
  ],
};

return [
  {
    json: {
      correlationId: ctx.correlationId,
      processInstanceId: ctx.processInstanceId,
      organizationId: ctx.organizationId,
      processingPath: ctx.processingPath,
      aiExecutionProfile: ctx.aiExecutionProfile,
      document,
      extraction,
      invoice,
      fieldEvidence,
      aiMeta: parsed.aiMeta,
    },
  },
];

// Single convergence point: consumes the merged outcome + ActivityExecution
// envelope ("Call Assemble ActivityExecution" -> "Merge ActivityExecution
// into outcome") and formats it for "04.2 Render control report". No
// aggregation logic of its own -- status/routing/controls all come from the
// real Phase 1 API's authoritative phase1ControlReport (see "03.1 Run
// DigiTax controls"), never recomputed here. This is the A1-review fix:
// Flow 1b no longer mirrors ORG-001 (or any other control) in n8n-side
// JavaScript.
const m = $input.first().json;

return [{
  json: {
    correlationId: m.correlationId,
    status: m.status,
    routing: m.routing,
    failedStep: m.failedStep,
    errorCode: m.errorCode,
    explanation: m.explanation,
    invoice: m.invoice,
    controls: m.report ? m.report.controls : null,
    report: m.report,
    organizationId: m.organizationId,
    processingPath: m.processingPath,
    aiExecutionProfile: m.aiExecutionProfile,
    aiProvider: m.aiProvider,
    modelId: m.modelId,
    modelVersion: m.modelVersion,
    processingLocation: m.processingLocation,
    promptVersion: m.promptVersion,
    fallbackUsed: m.fallbackUsed,
    activityExecution: m.activityExecution,
  },
}];

// Single convergence point for every success and failure branch. Renders
// self-contained HTML -- the demo audience must never need to inspect raw
// n8n execution JSON.
const r = $input.first().json;

function esc(s) {
  if (s === null || s === undefined) return "";
  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

const statusColors = { unauffaellig: "#1b7a3d", klaerung_erforderlich: "#a15c00", nicht_pruefbar: "#a11616" };
const statusColor = statusColors[r.status] || "#444";

const aiSummary = r.aiExecutionProfile
  ? `<p><b>AI execution:</b> ${esc(r.aiExecutionProfile)} via ${esc(r.aiProvider) || "(none)"} ${esc(r.modelId) || ""} -- processed ${esc(r.processingLocation) || "(unknown)"}, prompt ${esc(r.promptVersion) || "(unknown)"}, fallback used: ${r.fallbackUsed ? "yes" : "no"}</p>`
  : "";

let body;
if (r.controls) {
  const inv = r.invoice;
  const rows = r.controls.map((c) => `
    <tr>
      <td>${esc(c.controlId)}</td>
      <td>${esc(c.title)}</td>
      <td>${esc(c.outcome)}</td>
      <td>${esc(c.severity)}</td>
      <td>${esc((c.reasonCodes || []).join(", "))}</td>
      <td>${esc(c.message)}</td>
      <td><pre>${esc(c.details ? JSON.stringify(c.details, null, 2) : "")}</pre></td>
    </tr>`).join("");

  body = `
    <h2>Invoice ${esc(inv.invoiceNumber || "(missing)")} dated ${esc(inv.issueDate || "(missing)")}</h2>
    <p><b>Supplier (as read by OCR/LLM, not verified):</b> ${esc(inv.supplier.name)}</p>
    <p><b>Buyer (as read by OCR/LLM):</b> ${esc(inv.buyer.name)}, ${esc(inv.buyer.address.street)}, ${esc(inv.buyer.address.postalCode)} ${esc(inv.buyer.address.city)}, ${esc(inv.buyer.address.countryCode)}</p>
    <p><b>Organization profile:</b> ${esc(r.organizationId)}</p>
    ${aiSummary}
    <h3>Controls</h3>
    <table border="1" cellpadding="6" cellspacing="0">
      <tr><th>Control</th><th>Title</th><th>Outcome</th><th>Severity</th><th>Reason codes</th><th>Message</th><th>Details</th></tr>
      ${rows}
    </table>`;
} else {
  body = `
    <h2>Technical result -- no control was evaluated</h2>
    <p><b>Failed step:</b> ${esc(r.failedStep)}</p>
    <p><b>Error code:</b> ${esc(r.errorCode)}</p>
    <p><b>Explanation:</b> ${esc(r.explanation)}</p>
    ${aiSummary}`;
}

const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>DigiTax Flow 1b result</title>
<style>
  body { font-family: sans-serif; margin: 2rem; color: #1a1a1a; }
  .banner { padding: 1rem; border-radius: 6px; color: white; background: ${statusColor}; margin-bottom: 1rem; }
  .temp-notice { padding: 1rem; background: #fff3cd; border: 1px solid #d6b656; border-radius: 6px; margin-bottom: 1.5rem; }
  table { border-collapse: collapse; width: 100%; }
  th { background: #eee; text-align: left; }
  pre { white-space: pre-wrap; margin: 0; font-size: 0.85em; }
  .boundary { margin-top: 2rem; padding: 1rem; background: #f5f5f5; border-left: 4px solid #888; }
</style>
</head>
<body>
  <div class="temp-notice">
    <b>Local AI extraction is a concept.</b> This workflow performs OCR/LLM
    extraction (local or cloud, per the selected AI execution profile) in
    n8n, but every control below -- including ORG-001 -- is evaluated by the
    real, authoritative Phase 1 API (POST /v1/invoices/process-extracted),
    the same executor Flow 1a uses. What remains a concept: the local AI
    lane assumes an already-running, OpenAI-compatible local endpoint; no
    model is bundled or auto-started by this repository. See
    examples/n8n/README.md.
  </div>
  <div class="banner">
    <b>STATUS: ${esc(r.status)}</b> (routing: ${esc(r.routing)})<br>
    Correlation ID: ${esc(r.correlationId)}
  </div>
  ${body}
  <div class="boundary">
    This is a Flow 1b finding for human review only -- it is not an
    approval, rejection, booking, payment, or supplier communication.
  </div>
</body></html>`;

return [{ json: { ...r, html } }];

// Mirrors Flow 1a's own "Mark phase1 attempt start" nodes (own numbering
// to avoid colliding with this workflow's existing sequence, per
// examples/n8n/README.md). Also assembles the exact POST body
// "03.1 Run DigiTax controls" sends -- kept here, in a Code node, rather
// than built inline as an httpRequest expression, so the request shape is
// easy to read and test in one place.
const item = $input.first().json;
return [{
  json: {
    ...item,
    phase1AttemptStartedAt: new Date().toISOString(),
    processExtractedRequestBody: {
      organizationId: item.organizationId,
      document: item.document,
      extraction: item.extraction,
      invoice: item.invoice,
      fieldEvidence: item.fieldEvidence,
    },
  },
}];

// Same neverError contract as Flow 1a's "03.1 Run DigiTax controls": any
// HTTP response (2xx, 4xx, 5xx) lands here as normal output. Only a
// connection-level failure uses the node's error output and gets retried.
// A 4xx here is therefore guaranteed to have been retried zero times.
const ctx = $('01.2 Build run context').item.json;
const upstream = $('02.8 Mark phase1 attempt start').item.json;
const attemptStart = upstream.phase1AttemptStartedAt;
const aiMeta = upstream.aiMeta || {};
const resp = $input.first().json;
const statusCode = resp.statusCode;
const body = resp.body || {};

function baseFields() {
  return {
    processInstanceId: ctx.processInstanceId,
    correlationId: ctx.correlationId,
    workflowId: $workflow.id,
    receivedAt: ctx.receivedAt,
    phase1AttemptStartedAt: attemptStart,
    gateDecisionAt: null,
    organizationId: ctx.organizationId,
    processingPath: upstream.processingPath,
    aiExecutionProfile: upstream.aiExecutionProfile,
    aiProvider: aiMeta.aiProvider || null,
    modelId: aiMeta.modelId || null,
    modelVersion: aiMeta.modelVersion || null,
    processingLocation: aiMeta.processingLocation || null,
    promptVersion: aiMeta.promptVersion || null,
    fallbackUsed: aiMeta.fallbackUsed || false,
  };
}

if (statusCode >= 200 && statusCode < 300) {
  const invoice = body.canonicalInvoice.invoice;
  const document = body.canonicalInvoice.document;
  const report = body.phase1ControlReport;
  return [{
    json: {
      ...baseFields(),
      outcome: "REPORT",
      report,
      httpErrorCode: null,
      n8nErrorCode: null,
      explanation: null,
      phase1Status: report.status,
      routing: report.routing,
      failedStep: null,
      invoice,
      document,
    },
  }];
}

const apiDetail = (body.detail && typeof body.detail === "object") ? body.detail : {};
const httpErrorCode = apiDetail.error_code || `HTTP_${statusCode}`;
const retryNote = statusCode >= 400 && statusCode < 500
  ? "Not retried: this is a deterministic input/contract error."
  : "This response was received from the service (not a connection failure), so it was not subject to the connection-level retry either.";
const explanation = `${apiDetail.detail || `03.1 Run DigiTax controls returned HTTP ${statusCode}.`} (HTTP ${statusCode}). ${retryNote}`;

return [{
  json: {
    ...baseFields(),
    outcome: "HTTP_ERROR",
    report: null,
    httpErrorCode,
    n8nErrorCode: null,
    explanation,
    phase1Status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "03.1 Run DigiTax controls",
    invoice: null,
    document: null,
  },
}];

const ctx = $('01.2 Build run context').item.json;
const upstream = $('02.8 Mark phase1 attempt start').item.json;
const attemptStart = upstream.phase1AttemptStartedAt;
const aiMeta = upstream.aiMeta || {};
const ctxErr = $input.first().json;
const errObj = ctxErr.error || {};
const errMessage = (errObj.message || errObj || ctxErr.message || "").toString();
const errCode = (errObj.code || "").toString();
// Positively classify a timeout (ETIMEDOUT/ECONNABORTED, or a message
// mentioning "timeout") as TIMEOUT; every other connection-level failure is
// TRANSPORT_FAILURE.
const isTimeout = /ETIMEDOUT|ECONNABORTED/i.test(errCode) || /timeout/i.test(errMessage);
const outcome = isTimeout ? "TIMEOUT" : "TRANSPORT_FAILURE";
const n8nErrorCode = isTimeout ? "INVOICE_PROCESSING_SERVICE_TIMEOUT" : "INVOICE_PROCESSING_SERVICE_UNAVAILABLE";
const explanation = errMessage || "The invoice processing service did not respond after the bounded retry.";

return [{
  json: {
    processInstanceId: ctx.processInstanceId,
    correlationId: ctx.correlationId,
    workflowId: $workflow.id,
    receivedAt: ctx.receivedAt,
    outcome,
    report: null,
    httpErrorCode: null,
    n8nErrorCode,
    explanation,
    phase1AttemptStartedAt: attemptStart,
    gateDecisionAt: null,
    phase1Status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "03.1 Run DigiTax controls",
    invoice: null,
    document: null,
    organizationId: ctx.organizationId,
    processingPath: upstream.processingPath,
    aiExecutionProfile: upstream.aiExecutionProfile,
    aiProvider: aiMeta.aiProvider || null,
    modelId: aiMeta.modelId || null,
    modelVersion: aiMeta.modelVersion || null,
    processingLocation: aiMeta.processingLocation || null,
    promptVersion: aiMeta.promptVersion || null,
    fallbackUsed: aiMeta.fallbackUsed || false,
  },
}];

// Reconciles the shared subworkflow's minimal { activityExecution } return
// with the branch's own normalized envelope (phase1Status/routing/report/
// AI-selection audit fields/...) that "04.1 Build control report" still
// expects -- the shared subworkflow's contract stays reusable/minimal on
// purpose (see examples/n8n/README.md), so this node does the reconciling,
// same pattern as every Flow 1a workflow.
function tryGetBranchEnvelope(nodeName) {
  try {
    const item = $(nodeName).item;
    return item ? item.json : undefined;
  } catch (e) {
    return undefined;
  }
}

const BRANCH_NODE_NAMES = [
  "01.5 Handle invalid upload",
  "01.11 Handle unresolved AI profile",
  "02.4 Handle OCR service failure",
  "02.6 Handle OCR parse failure",
  "02.4L Handle local OCR service failure",
  "02.6L Handle local OCR parse failure",
  "03.2 Classify controls response",
  "03.3 Handle controls-call failure",
];

let envelope;
for (const name of BRANCH_NODE_NAMES) {
  const candidate = tryGetBranchEnvelope(name);
  if (candidate !== undefined) {
    envelope = candidate;
    break;
  }
}
if (!envelope) {
  throw new Error("ACTIVITY_EXECUTION_MERGE_NO_BRANCH_ENVELOPE: could not locate the originating branch node's output.");
}

const { activityExecution } = $input.first().json;

return [{
  json: {
    correlationId: envelope.correlationId,
    processInstanceId: envelope.processInstanceId,
    status: envelope.phase1Status,
    routing: envelope.routing,
    failedStep: envelope.failedStep,
    errorCode: envelope.httpErrorCode || envelope.n8nErrorCode,
    explanation: envelope.explanation,
    invoice: envelope.invoice,
    document: envelope.document,
    report: envelope.report,
    organizationId: envelope.organizationId,
    processingPath: envelope.processingPath,
    aiExecutionProfile: envelope.aiExecutionProfile,
    aiProvider: envelope.aiProvider,
    modelId: envelope.modelId,
    modelVersion: envelope.modelVersion,
    processingLocation: envelope.processingLocation,
    promptVersion: envelope.promptVersion,
    fallbackUsed: envelope.fallbackUsed,
    activityExecution,
  },
}];
